patch:
diff --git a/repro-no-var-fix-reference-error.js b/repro-no-var-fix-reference-error.js
new file mode 100644
index 0000000..d137270
--- /dev/null
+++ b/repro-no-var-fix-reference-error.js
@@ -0,0 +1,46 @@
+"use strict";
+
+// Usage: node repro-no-var-fix-reference-error.js [path-to-eslint-package]
+// Default: the eslint in this checkout (./lib/api.js).
+// Exits 1 if `no-var` autofix turns the code into something that throws a ReferenceError.
+
+const path = require("path");
+const target = process.argv[2]
+    ? path.resolve(process.argv[2])
+    : path.resolve(__dirname, "lib/api.js");
+const { ESLint } = require(target);
+const version = process.argv[2]
+    ? require(path.join(target, "package.json")).version
+    : require("./package.json").version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+(async () => {
+    const eslint = new ESLint({
+        overrideConfigFile: true,
+        overrideConfig: [{ rules: { "no-var": ["error"] } }],
+        fix: true,
+    });
+    const [result] = await eslint.lintText(code, { filePath: "example.js" });
+    const output = result.output === undefined ? code : result.output;
+
+    console.log(`eslint ${version}`);
+    console.log("messages remaining after fix:", result.messages.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId})`));
+    console.log("fixed:", result.output !== undefined);
+    console.log("--- output after --fix ---");
+    console.log(output);
+
+    // Run the fixed function body (drop `export`) and call it.
+    try {
+        new Function(`${output.replace("export ", "")}\na();`)();
+        console.log("RESULT: fixed code runs without error");
+    } catch (e) {
+        console.log(`RESULT: fixed code throws ${e.name}: ${e.message}`);
+        process.exitCode = 1;
+    }
+})();
